.timer on
PRAGMA temp_store; PRAGMA threads;
SELECT 'default', COUNT(*) FROM (SELECT domain, client_ip, source_id, CAST(event_time_s/900 AS INT) b, COUNT(*) FROM queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY 1,2,3,4);
SELECT 'default id', COUNT(*) FROM (SELECT source_id, client_ip, client_name FROM queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 GROUP BY 1,2,3);
